return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'kn','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-25T15:09:53+00:00','po-revision-date'=>'2026-09-25T15:09:53+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'ಪುನರ್ನಿರ್ಮಿತ Page Builder Sandwich-ನ ಫೌಂಡೇಶನ್ ರಿಲೀಸ್: ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಮತ್ತು ಕುರಿತು ಪರದೆ, ಫುಟ್‌ಪ್ರಿಂಟ್-ರಹಿತ ಮುಂಭಾಗದ ಔಟ್‌ಪುಟ್ ಲೇಯರ್, ಮತ್ತು ಒಂದು ಮಾದರಿ ಕಂಟೆಂಟ್ ಬ್ಲಾಕ್.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Sorry, you are not allowed to access this page.'=>'ಕ್ಷಮಿಸಿ, ನಿಮಗೆ ಈ ಪುಟವನ್ನು ಪ್ರವೇಶಿಸಲು ಅನುಮತಿಯಿಲ್ಲ.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'ಈ ಪ್ಲಗಿನ್ ನ ಪ್ರತಿಯಿಂದ ನಿರ್ವಾಹಕ ಪರದೆಯ ಸ್ಕ್ರಿಪ್ಟ್‌ಗಳು ಕಾಣೆಯಾಗಿವೆ. ಬಿಡುಗಡೆಯಾದ ಪ್ಯಾಕೇಜ್‌ನಿಂದ ಇದನ್ನು ಮರುಸ್ಥಾಪಿಸಿ.','This screen needs JavaScript.'=>'ಈ ಪರದೆಗೆ ಜಾವಾಸ್ಕ್ರಿಪ್ಟ್ (JavaScript) ಅಗತ್ಯವಿದೆ.','Languages'=>'ಭಾಷೆಗಳು','Upgrade'=>'ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡಿ','Pricing'=>'ಬೆಲೆ ನಿಗದಿಸುವುದು','Start Trial'=>'ಪ್ರಾರಂಭಿಸಿ ಟ್ರಯಲ್','Account'=>'ಖಾತೆ','Contact Us'=>'ನಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಿ','Affiliation'=>'ಸಂಯೋಜನೆ','the kind of softwarePlugin'=>'ಪ್ಲಗಿನ್','greetingHey %s,'=>'ಹೇ %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'ಭದ್ರತೆ ಮತ್ತು ವೈಶಿಷ್ಟ್ಯದ ನವೀಕರಣಗಳು, ಶೈಕ್ಷಣಿಕ ವಿಷಯ ಮತ್ತು ಸಾಂದರ್ಭಿಕ ಕೊಡುಗೆಗಳಿಗಾಗಿ ಇಮೇಲ್ ಅಧಿಸೂಚನೆಗಳನ್ನು ಸ್ವೀಕರಿಸಲು ಮತ್